/* Core tests: file number normalization (must match the backend) and the offline store/search. */
#include <SDL3/SDL.h>
#include <SDL3/SDL_main.h>

#include "db.h"
#include "fileno.h"
#include "pdf.h"

static int failures = 0;
#define CHECK(cond) do { if (!(cond)) { failures++; SDL_Log("FAIL %s:%d: %s", __FILE__, __LINE__, #cond); } } while (0)
#define CHECK_STR(a, b) do { if (SDL_strcmp((a), (b)) != 0) { failures++; SDL_Log("FAIL %s:%d: \"%s\" != \"%s\"", __FILE__, __LINE__, (a), (b)); } } while (0)

static void test_fileno(void)
{
    /* Same cases as backend/test/api.test.js */
    const char *variants[] = {"F-0042", "f 42", " F_042 ", "F--42"};
    char out[FILENO_MAX + 1];
    for (size_t i = 0; i < SDL_arraysize(variants); i++) {
        fileno_normalize(variants[i], out, sizeof out);
        CHECK_STR(out, "F-42");
    }
    fileno_normalize("2024/007/B", out, sizeof out);
    CHECK_STR(out, "2024-7-B");
    fileno_normalize("000", out, sizeof out);
    CHECK_STR(out, "0");
    fileno_normalize("A0B 10", out, sizeof out);
    CHECK_STR(out, "A0B-10");
    CHECK(fileno_normalize("--", out, sizeof out) == 0);

    CHECK(fileno_from_qr("MYFILES:F-0042", out, sizeof out));
    CHECK_STR(out, "F-42");
    CHECK(!fileno_from_qr("https://example.com", out, sizeof out));
}

static void test_tags(void)
{
    char out[64];
    tags_distinct("tax, Bank,tax , ,house,TAX", out, sizeof out);
    CHECK_STR(out, "tax, Bank, house");
    tags_distinct("", out, sizeof out);
    CHECK_STR(out, "");
    tags_distinct(" , ,", out, sizeof out);
    CHECK_STR(out, "");
    tags_distinct("aaaa,bbbb,cccc", out, 12); /* stops at whole tags when out of room */
    CHECK_STR(out, "aaaa, bbbb");
}

static void test_db(const char *path)
{
    SDL_RemovePath(path);
    Db *db = db_open(path);
    CHECK(db != NULL);
    if (!db) return;

    char next[FILENO_MAX + 1];
    db_folder_suggest_next(db, next, sizeof next);
    CHECK_STR(next, "F-0001");

    Folder f = {0};
    SDL_strlcpy(f.file_number, "F-0042", sizeof f.file_number);
    SDL_strlcpy(f.title, "House papers", sizeof f.title);
    CHECK(db_folder_save(db, &f));
    CHECK_STR(f.id, "F-42");

    db_folder_suggest_next(db, next, sizeof next);
    CHECK_STR(next, "F-0043");

    Document d = {0};
    SDL_strlcpy(d.folder_id, f.id, sizeof d.folder_id);
    SDL_strlcpy(d.title, "Electricity bill", sizeof d.title);
    CHECK(db_document_save(db, &d));
    char pid[ID_LEN];
    new_id(pid);
    CHECK(db_page_add(db, d.id, pid, "x.jpg", 100, 200, "BESCOM consumer number 7781 amount due"));
    new_id(pid);
    CHECK(db_page_add(db, d.id, pid, "y.jpg", 100, 200, "Page two: meter reading"));

    Page pages[4];
    CHECK(db_page_list(db, d.id, pages, 4) == 2);
    CHECK(pages[1].page_no == 2);

    Document d2 = {0};
    SDL_strlcpy(d2.folder_id, f.id, sizeof d2.folder_id);
    SDL_strlcpy(d2.title, "Water bill", sizeof d2.title);
    SDL_strlcpy(d2.tags, "Utility, water", sizeof d2.tags);
    CHECK(db_document_save(db, &d2));
    SDL_strlcpy(d.tags, "utility,tax", sizeof d.tags);
    CHECK(db_document_save(db, &d));
    Folder tagged;
    CHECK(db_folder_get(db, f.id, &tagged));
    CHECK(SDL_strstr(tagged.tags, "water") && SDL_strstr(tagged.tags, "tax") && tagged.doc_count == 2);
    int commas = 0;
    for (const char *c = tagged.tags; *c; c++) commas += *c == ',';
    CHECK(commas == 2); /* utility (both spellings), tax, water: exactly 3 distinct tags */
    char once[64];
    tags_distinct(tagged.tags, once, sizeof once);
    CHECK_STR(once, tagged.tags); /* already distinct */
    CHECK(db_document_delete(db, d2.id));

    SearchHit hits[8];
    int n = db_search(db, "bescom", hits, 8);
    CHECK(n == 1);
    if (n == 1) {
        CHECK_STR(hits[0].file_number, "F-0042");
        CHECK(SDL_strstr(hits[0].snippet, "[BESCOM]") != NULL);
        CHECK_STR(hits[0].tags, "utility, tax");
    }
    CHECK(db_search(db, "mete", hits, 8) == 1);         /* prefix match, second page */
    CHECK(db_search(db, "house", hits, 8) == 1);        /* folder title is searchable */
    CHECK(db_search(db, "F 42", hits, 8) == 1);         /* normalized file number */
    CHECK(db_search(db, "F-0042", hits, 8) == 1);       /* display file number */
    CHECK(db_search(db, "electricity water", hits, 8) == 0); /* all words must match */
    CHECK(db_search(db, "\"OR NEAR(", hits, 8) == 0);   /* FTS syntax is neutralised, no error */

    Folder folders[8];
    CHECK(db_search_folders(db, "f42", folders, 8) == 0); /* "f42" is a different number than "F-42" */
    CHECK(db_search_folders(db, "f 0042", folders, 8) == 1);
    CHECK(db_search_folders(db, "house", folders, 8) == 1);

    /* Renaming the folder re-indexes its documents. */
    SDL_strlcpy(f.title, "Utilities", sizeof f.title);
    CHECK(db_folder_save(db, &f));
    CHECK(db_search(db, "house", hits, 8) == 0);
    CHECK(db_search(db, "utilities", hits, 8) == 1);

    /* Renumbering moves the documents to the new envelope id. */
    SDL_strlcpy(f.file_number, "B-7", sizeof f.file_number);
    CHECK(db_folder_save(db, &f));
    CHECK_STR(f.id, "B-7");
    Folder got;
    CHECK(!db_folder_get(db, "F-42", &got));
    CHECK(db_folder_get(db, "B-7", &got) && got.doc_count == 1);
    n = db_search(db, "bescom", hits, 8);
    CHECK(n == 1 && SDL_strcmp(hits[0].file_number, "B-7") == 0);

    SyncCounts c;
    db_sync_counts(db, &c);
    CHECK(c.pending_images == 2);
    CHECK(c.pending_rows >= 4);

    /* Deleting the folder hides its documents from search. */
    CHECK(db_folder_delete(db, "B-7"));
    CHECK(db_search(db, "bescom", hits, 8) == 0);
    CHECK(db_folder_list(db, folders, 8) == 0);

    char v[64];
    CHECK(!db_meta_get(db, "token", v, sizeof v));
    CHECK(db_meta_set(db, "token", "abc"));
    CHECK(db_meta_get(db, "token", v, sizeof v));
    CHECK_STR(v, "abc");

    db_close(db);
    SDL_RemovePath(path);
}

