/* strstr for binary data (embedded JPEGs contain NUL bytes). */
static bool contains(const char *buf, size_t len, const char *needle)
{
    size_t n = SDL_strlen(needle);
    for (size_t i = 0; i + n <= len; i++)
        if (SDL_memcmp(buf + i, needle, n) == 0) return true;
    return false;
}

static void test_pdf(const char *dir)
{
    char rgb[1200], gray[1200], bogus[1200], out[1200];
    SDL_snprintf(rgb, sizeof rgb, "%spdf-rgb.jpg", dir);
    SDL_snprintf(gray, sizeof gray, "%spdf-gray.jpg", dir);
    SDL_snprintf(bogus, sizeof bogus, "%spdf-bogus.jpg", dir);
    SDL_snprintf(out, sizeof out, "%spdf-test.pdf", dir);
    CHECK(SDL_SaveFile(rgb, JPEG_RGB, sizeof JPEG_RGB));
    CHECK(SDL_SaveFile(gray, JPEG_GRAY, sizeof JPEG_GRAY));
    CHECK(SDL_SaveFile(bogus, "not a jpeg", 10));

    const char *paths[] = {rgb, bogus, gray};
    CHECK(pdf_from_jpegs(paths, 3, out) == 2); /* the bogus file is skipped */
    size_t len = 0;
    char *pdf = SDL_LoadFile(out, &len);
    CHECK(pdf && len > sizeof JPEG_RGB + sizeof JPEG_GRAY);
    if (pdf) {
        CHECK(SDL_strncmp(pdf, "%PDF-1.4", 8) == 0);
        CHECK(contains(pdf, len, "/Count 2"));
        CHECK(contains(pdf, len, "/Width 40 /Height 60 /ColorSpace /DeviceRGB"));
        CHECK(contains(pdf, len, "/Width 60 /Height 40 /ColorSpace /DeviceGray"));
        CHECK(SDL_strncmp(pdf + len - 6, "%%EOF\n", 6) == 0);
    }
    SDL_free(pdf);

    const char *only_bogus[] = {bogus};
    CHECK(pdf_from_jpegs(only_bogus, 1, out) == 0); /* nothing usable: no PDF, old one untouched */
    SDL_RemovePath(rgb);
    SDL_RemovePath(gray);
    SDL_RemovePath(bogus);
    if (!SDL_getenv("KEEP_TEST_PDF")) SDL_RemovePath(out);
}

int main(int argc, char **argv)
{
    (void)argc; (void)argv;
    test_fileno();
    test_tags();
    char *path = NULL;
    SDL_asprintf(&path, "%smyfiles-test-%llu.db", SDL_GetBasePath(), (unsigned long long)SDL_GetTicksNS());
    test_db(path);
    SDL_free(path);
    test_pdf(SDL_GetBasePath());
    SDL_Log("%s (%d failures)", failures ? "FAILED" : "OK", failures);
    return failures ? 1 : 0;
}
